import React, { useState, useEffect } from "react";
import axios from "axios";

const ProjectROIEntry = ({ intakeNumber }) => {
  const [rows, setRows] = useState([
    {
      Release: "",
      ROIMonth: "",
      SavingsCategory: "",
      AutomationFmk: "",
      TotalTCsCount: "",
      ManualTCsPD: "",
      AutomatedTCCreatedPD: "",
      NumberofCycles: "",
      ProjectName: "",
      AutomationLead: "",
      FormulaValue: "" // example calculated field
    },
  ]);
  const [projectDetails, setProjectDetails] = useState(null);

  // Fetch project details (ProjectName + AutomationLead)
  useEffect(() => {
    if (intakeNumber) {
      axios.get(`http://localhost:5000/api/projects/${intakeNumber}`)
        .then((res) => {
          setProjectDetails(res.data);
          setRows((prev) =>
            prev.map((row) => ({
              ...row,
              ProjectName: res.data.ProjectName,
              AutomationLead: res.data.AutomationLead
            }))
          );
        })
        .catch((err) => console.error("Error fetching project details", err));
    }
  }, [intakeNumber]);

  // Handle input change
  const handleChange = (index, field, value) => {
    const newRows = [...rows];
    newRows[index][field] = value;

    // Example formula-driven calculation (disabled field)
    newRows[index].FormulaValue =
      (parseInt(newRows[index].TotalTCsCount || 0) -
        parseInt(newRows[index].AutomatedTCCreatedPD || 0)) *
      (parseInt(newRows[index].NumberofCycles || 1));

    setRows(newRows);
  };

  // Add a new row
  const addRow = () => {
    setRows([
      ...rows,
      {
        Release: "",
        ROIMonth: "",
        SavingsCategory: "",
        AutomationFmk: "",
        TotalTCsCount: "",
        ManualTCsPD: "",
        AutomatedTCCreatedPD: "",
        NumberofCycles: "",
        ProjectName: projectDetails?.ProjectName || "",
        AutomationLead: projectDetails?.AutomationLead || "",
        FormulaValue: ""
      },
    ]);
  };

  // Save rows
  const saveRows = () => {
    const payload = {
      entries: rows.map((row) => ({
        intake_number: intakeNumber,
        ...row
      })),
    };

    axios.post("http://localhost:5000/api/projectroientry", payload)
      .then((res) => alert("Entries saved successfully"))
      .catch((err) => alert("Error saving entries"));
  };

  return (
    <div className="p-4">
      <h2 className="text-xl font-bold mb-4">Project ROI Entry</h2>
      {rows.map((row, index) => (
        <div key={index} className="grid grid-cols-6 gap-4 mb-4 border p-3 rounded-lg shadow">
          <input
            type="text"
            placeholder="Release"
            value={row.Release}
            onChange={(e) => handleChange(index, "Release", e.target.value)}
          />
          <input
            type="text"
            placeholder="ROI Month"
            value={row.ROIMonth}
            onChange={(e) => handleChange(index, "ROIMonth", e.target.value)}
          />
          <select
            value={row.SavingsCategory}
            onChange={(e) => handleChange(index, "SavingsCategory", e.target.value)}
          >
            <option value="">Select Savings Category</option>
            <option value="Infra">Infra</option>
            <option value="License">License</option>
            <option value="Productivity">Productivity</option>
          </select>
          <select
            value={row.AutomationFmk}
            onChange={(e) => handleChange(index, "AutomationFmk", e.target.value)}
          >
            <option value="">Select Framework</option>
            <option value="Selenium">Selenium</option>
            <option value="Playwright">Playwright</option>
            <option value="Cypress">Cypress</option>
          </select>
          <input
            type="number"
            placeholder="Total TCs Count"
            value={row.TotalTCsCount}
            onChange={(e) => handleChange(index, "TotalTCsCount", e.target.value)}
          />
          <input
            type="number"
            placeholder="Manual TCs PD"
            value={row.ManualTCsPD}
            onChange={(e) => handleChange(index, "ManualTCsPD", e.target.value)}
          />
          <input
            type="number"
            placeholder="Automated TC Created PD"
            value={row.AutomatedTCCreatedPD}
            onChange={(e) => handleChange(index, "AutomatedTCCreatedPD", e.target.value)}
          />
          <input
            type="number"
            placeholder="Number of Cycles"
            value={row.NumberofCycles}
            onChange={(e) => handleChange(index, "NumberofCycles", e.target.value)}
          />
          <input
            type="text"
            value={row.ProjectName}
            disabled
          />
          <input
            type="text"
            value={row.AutomationLead}
            disabled
          />
          <input
            type="text"
            value={row.FormulaValue}
            disabled
          />
        </div>
      ))}
      <button onClick={addRow} className="px-4 py-2 bg-blue-500 text-white rounded mr-2">Add Row</button>
      <button onClick={saveRows} className="px-4 py-2 bg-green-500 text-white rounded">Save</button>
    </div>
  );
};

export default ProjectROIEntry;
